import { TfiClose } from "react-icons/tfi";
import { BsGithub } from "react-icons/bs";
import { FaDownload, FaPlay } from "react-icons/fa";
import ImageCarousel from "../carousel/ImageCarousel";

const Modal = ({ item, onClose }) => {
  if (!item) return null;

  return (
    <div className="fixed inset-0 z-[9999] flex items-center justify-center">
      {/* Fondo */}
      <div
        onClick={onClose}
        className="fixed inset-0 bg-black/60 backdrop-blur-sm"
      ></div>

      {/* Wrapper (IMPORTANTE: aquí va el border + overflow hidden) */}
      <div
        className="
          relative z-50
          w-[92%] max-w-[900px]
          rounded-2xl
          bg-[var(--card-color)]
          shadow-[0_20px_60px_rgba(0,0,0,0.5)]
          overflow-hidden
          animate-[fadeIn_.3s_ease]
        "
      >
        {/* Contenido con scroll */}
        <div className="flex flex-col gap-6 max-h-[90vh] overflow-y-auto no-scrollbar p-5 lg:p-8">

          {/* Imagen */}
          <div className="w-full">
            <div className="w-full rounded-xl overflow-hidden bg-white p-2">
              <ImageCarousel
                media={
                  item.media
                    ? item.media
                    : item.image
                      ? [{ type: "image", src: item.image }]
                      : []
                }
              />
            </div>
          </div>

          {/* Texto */}
          <div className="flex flex-col">
            <h3 className="text-2xl font-bold text-[var(--title-color)] mb-2 text-center">
              {item.title}
            </h3>

            <p className="text-xs font-medium text-[var(--first-color)] mb-4 text-center">
              {item.technologies}
            </p>

            <p className="text-sm leading-relaxed text-[var(--text-color)] mb-6 text-justify">
              {item.description}
            </p>

            {/* Botones */}
            <div className="flex flex-wrap justify-center gap-4">
              {/* Codigo */}
              {item.github && (
                <a
                  href={item.github}
                  target="_blank"
                  rel="noopener noreferrer"
                  className="
                    inline-flex items-center gap-2
                    px-4 py-2
                    rounded-full
                    border border-[var(--first-color)]
                    text-[var(--first-color)]
                    text-sm
                    transition-all duration-300
                    hover:bg-[var(--first-color)]
                    hover:text-black
                    hover:-translate-y-1
                    hover:shadow-lg
                  "
                >
                  <BsGithub /> Código
                </a>
              )}
              {/* Demo */}
              {item.demo && (
                <a
                  href={item.demo}
                  target="_blank"
                  rel="noopener noreferrer"
                  className="
                    inline-flex items-center gap-2
                    px-4 py-2
                    rounded-full
                    bg-[var(--first-color)]
                    text-black
                    text-sm
                    font-medium
                    transition-all duration-300
                    hover:-translate-y-1
                    hover:shadow-lg
                  "
                >
                  <FaPlay /> Demo
                </a>
              )}
              {/* Instalador */}
              {item.installer && (
                <a
                  href={item.installer}
                  target="_blank"
                  rel="noopener noreferrer"
                  className="
                    inline-flex items-center gap-2
                    px-4 py-2
                    rounded-full
                    bg-[var(--first-color)]
                    text-black
                    text-sm
                    font-medium
                    transition-all duration-300
                    hover:-translate-y-1
                    hover:shadow-lg
                  "
                >
                  <FaDownload /> Instalador
                </a>
              )}
            </div>
          </div>
        </div>

        {/* Botón cerrar */}
        <button
          onClick={onClose}
          className="
            absolute top-4 right-4
            bg-black/40
            p-2
            rounded-full
            text-white
            hover:scale-110
            transition
          "
        >
          <TfiClose />
        </button>
      </div>
    </div>
  );
};

export default Modal;