import React, { useEffect, useState } from "react";
import { projectsData, projectsNav } from "./Data";
import WorksItems from "./WorksItems";

const Work = () => {
  const ITEMS_INICIAL = 3;
  const [visibleCount, setVisibleCount] = useState(ITEMS_INICIAL);

  const [item, setItem] = useState({ name: "todos" });
  const [projects, setProjects] = useState([]);
  const [active, setActive] = useState(0);

  useEffect(() => {
    const sorted = (list) =>
      [...list].sort((a, b) => new Date(b.date) - new Date(a.date));

    if (item.name === "todos") {
      setProjects(sorted(projectsData));
    } else {
      const newProjects = projectsData.filter(
        (project) => project.category.toLowerCase() === item.name
      );
      setProjects(sorted(newProjects));
    }

    setVisibleCount(ITEMS_INICIAL);
  }, [item]);

  const handleClick = (e, index) => {
    setItem({ name: e.target.textContent.toLowerCase() });
    setActive(index);
  };

  return (
    <div>
      {/* Filtros */}
      <div
        data-aos="flip-left"
        data-aos-duration="1000"
        className="flex flex-wrap justify-center gap-3 mb-8"
      >
        {projectsNav.map((navItem, index) => (
          <span
            key={index}
            onClick={(e) => handleClick(e, index)}
            className={`
              px-4 py-1.5 rounded-full cursor-pointer text-sm font-medium
              transition-colors duration-300
              ${active === index
                ? "bg-[var(--button-color)] text-[var(--container-color)]"
                : "text-[var(--title-color)] hover:bg-[var(--button-color)] hover:text-[var(--container-color)]"
              }
            `}
          >
            {navItem.name}
          </span>
        ))}
      </div>

      {/* Grid de proyectos */}
      <div className=" grid gap-8 grid-cols-[repeat(auto-fit,minmax(280px,1fr))] max-w-[1200px] mx-auto">
        {/* <div className=" grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-8 max-w-[1200px] mx-auto"> */}
        {projects.slice(0, visibleCount).map((item) => (
          <WorksItems item={item} key={item.id} />
        ))}
      </div>

      {/* Botón mostrar más / menos */}
      {projects.length > ITEMS_INICIAL && (
        <div className="flex justify-center mt-12">
          {visibleCount < projects.length ? (
            <button
              onClick={() => setVisibleCount((prev) => prev + 4)}
              className="px-6 py-2 rounded-full border-2 border-[var(--first-color)] text-[var(--first-color)] bg-transparent text-sm inline-flex items-center gap-2 transition-all duration-300 hover:bg-[var(--first-color)] hover:text-black hover:-translate-y-1 hover:shadow-lg active:scale-95 ">
              Mostrar más
            </button>
          ) : (
            <button
              onClick={() => {
                setVisibleCount(ITEMS_INICIAL);
                const section = document.getElementById("proyectos");
                if (section) {
                  section.scrollIntoView({ behavior: "smooth" });
                }
              }}
              className="px-6 py-2 rounded-full border-2 border-[var(--first-color)] text-[var(--first-color)] bg-transparent text-sm inline-flex items-center gap-2 transition-all duration-300 hover:bg-[var(--first-color)] hover:text-black hover:-translate-y-1 hover:shadow-lg active:scale-95 ">
              Mostrar menos
            </button>
          )}
        </div>
      )}
    </div>
  );
};

export default Work;
