// export default TimelineItem;


import React from "react";

const TimelineItem = ({ item, isLeft }) => {
  return (
    <div className="relative group">
      {/* Desktop: grid normal */}
      <div className="hidden md:grid grid-cols-[1fr_40px_1fr] items-center">
        {/* Contenido izquierdo */}
        {isLeft ? (
          <div className="md:text-right p-4 rounded-lg transition group-hover:bg-white">
            <h3 className="text-lg font-semibold">{item.title}</h3>
            <span className="block text-sm text-gray-600 mt-1">{item.subtitle}</span>
            <span className="block text-xs text-gray-400 mt-1">{item.place}</span>
            <span className="text-xs text-gray-500 mt-1">📅 {item.date}</span>
          </div>
        ) : (
          <div></div>
        )}

        {/* Columna central */}
        <div className="flex justify-center relative">
          <div className="w-6 h-6 bg-white border-2 border-gray-300 rounded-full shadow-lg z-10 relative transition-all duration-300 group-hover:scale-125"></div>
        </div>

        {/* Contenido derecho */}
        {!isLeft ? (
          <div className="md:text-left p-4 rounded-lg transition group-hover:bg-white">
            <h3 className="text-lg font-semibold">{item.title}</h3>
            <span className="block text-sm text-gray-600 mt-1">{item.subtitle}</span>
            <span className="block text-xs text-gray-400 mt-1">{item.place}</span>
            <span className="text-xs text-gray-500 mt-1">📅 {item.date}</span>
          </div>
        ) : (
          <div></div>
        )}
      </div>

      {/* Mobile: línea y círculo a la izquierda, contenido a la derecha */}
      <div className="flex md:hidden items-start relative mb-2 group mx-2">
        {/* Línea vertical */}
        <div className="absolute left-3 top-5 w-[2px] h-full bg-gray-300 z-0"></div>

        {/* Círculo */}
        <div className="w-6 h-6 bg-white border-2 border-gray-300 rounded-full shadow-lg z-10 relative transition-transform duration-300 group-hover:scale-125"></div>

        {/* Contenido */}
        <div className="ml-6 w-full max-w-xs p-4 rounded-lg bg-white shadow-sm transition-colors duration-300 group-hover:bg-gray-50">
          <h3 className="text-lg font-semibold">{item.title}</h3>
          <span className="block text-sm text-gray-600 mt-1">{item.subtitle}</span>
          <span className="block text-xs text-gray-400 mt-1">{item.place}</span>
          <span className="text-xs text-gray-500 mt-1">📅 {item.date}</span>
        </div>
      </div>


    </div>
  );
};

export default TimelineItem;
